// Fix01C2 — metrics screen copy generated by the metrics UI helpers.
//
// Note on scope (recorded): an end-to-end assertion through dealerAdminMetricsView with
// `DealerDeps{}` is impossible today — buildOperationalMetrics dereferences nil repositories
// (`repositories.(*WebhookDeliveryRepo).CountByStatus` via metrics.go:180, reached from
// dealer.go:6203) and panics before any view text exists. That blocker is recorded in the
// FIX-01C2 report; the DB-backed view assertion belongs to ZH-04/TEST-01C. The assertions
// below cover the same functions the view calls, with the view wiring pinned separately.

func seriesItem(name, labels, value string, numeric float64) dealerPromMetricSeries {
	return dealerPromMetricSeries{name: name, labels: labels, displayValue: value, hasNumeric: true, numeric: numeric}
}

func TestFix01C2GroupTextAndDisplayNamesFollowLocale(t *testing.T) {
	for _, key := range []string{"runtime", "operations", "money-events", "chain", "wallet-index", "collectors", "unknown-group"} {
		zhTitle, zhSummary := dealerMetricGroupText(localization.ZHCN, key)
		enTitle, enSummary := dealerMetricGroupText(localization.EN, key)
		if enTitle == "" || enSummary == "" {
			t.Fatalf("group %q has no English text", key)
		}
		if zhTitle == enTitle || zhSummary == enSummary {
			t.Errorf("group %q is not localized: title=%q summary=%q", key, zhTitle, zhSummary)
		}
		if !containsCJK(zhTitle) || !containsCJK(zhSummary) {
			t.Errorf("group %q zh text has no Chinese: %q / %q", key, zhTitle, zhSummary)
		}
	}
	// exact approved wording for two representative groups
	if title, _ := dealerMetricGroupText(localization.ZHCN, "operations"); title != "运营积压" {
		t.Errorf("operations title = %q", title)
	}
	if title, _ := dealerMetricGroupText(localization.ZHCN, "collectors"); title != "采集器错误" {
		t.Errorf("collectors title = %q", title)
	}

	for _, name := range []string{"gateway_build_info", "gateway_sweep_job_backlog", "gateway_provider_health", "gateway_metrics_collection_error"} {
		zh := dealerMetricDisplayName(localization.ZHCN, name)
		en := dealerMetricDisplayName(localization.EN, name)
		if zh == en || !containsCJK(zh) {
			t.Errorf("display name %q not localized: zh=%q en=%q", name, zh, en)
		}
	}
	// unknown metric names keep the trimmed identifier, never a key
	if got := dealerMetricDisplayName(localization.ZHCN, "gateway_vendor_custom"); got != "vendor_custom" {
		t.Errorf("unknown fallback = %q, want the trimmed identifier", got)
	}
	for _, raw := range []string{"%s", `<script>alert(1)</script>`} {
		if got := dealerMetricDisplayName(localization.ZHCN, raw); got != raw {
			t.Errorf("fallback %q was altered: %q", raw, got)
		}
	}
}

func TestFix01C2NarrativeScenariosAndFormats(t *testing.T) {
	tests := []struct {
		name     string
		item     dealerPromMetricSeries
		zhDesc   string
		zhAction string
	}{
		{"collector failure", seriesItem("gateway_metrics_collection_error", "", "2", 2), "采集器无法读取数据；本页可能不完整或具有误导性。", "使用采集器与原因标签检查相关仓库/查询日志。"},
		{"production gate", seriesItem("gateway_production_signer_ready", "", "0", 0), "生产门禁未就绪；出站安全假设似乎不完整。", "核实签名器模式、外部托管适配器健康与生产环境设置。"},
		{"provider failure", seriesItem("gateway_provider_consecutive_failures", `provider="rpc1"`, "3", 3), "提供方探测连续出错。", "检查 RPC 端点、速率限制与故障转移顺序。"},
		{"dead letter", seriesItem("gateway_webhook_delivery_backlog", `status="dead_letter"`, "5", 5), "存在需要人工介入的死信记录。", "在相应队列/任务页面处理记录，修复原因或重新入队。"},
		{"backlog", seriesItem("gateway_refund_backlog", `status="pending"`, "4", 4), "存在等待处理的活跃记录。", "检查 worker 租约、吞吐量与最旧记录时长。"},
		{"no action", seriesItem("gateway_chain_worker_count", "", "3", 3), "该信号用于常规运营跟踪监控。", "无需操作。"},
	}
	for _, tc := range tests {
		zhDesc, zhAction := dealerMetricNarrative(localization.ZHCN, tc.item)
		if zhDesc != tc.zhDesc || zhAction != tc.zhAction {
			t.Errorf("%s: zh narrative = (%q, %q), want (%q, %q)", tc.name, zhDesc, zhAction, tc.zhDesc, tc.zhAction)
		}
		enDesc, enAction := dealerMetricNarrative(localization.EN, tc.item)
		if enDesc == "" || enAction == "" || enDesc == zhDesc {
			t.Errorf("%s: english narrative missing or identical: (%q, %q)", tc.name, enDesc, enAction)
		}
	}
	// unknown single series keeps the neutral guidance, localized.
	unknown := seriesItem("gateway_vendor_custom", "", "%s", 1)
	if _, zhAction := dealerMetricNarrative(localization.ZHCN, unknown); zhAction != "无需操作。" {
		t.Errorf("unknown fallback action = %q", zhAction)
	}

	// alert detail: trusted formats, args in order, user values never interpreted
	hostile := seriesItem("gateway_refund_backlog", `status="failed"`, "%s $1 <script>alert(1)</script>", 2)
	global := dealerMetricAlertDetail(localization.ZHCN, hostile, "退款", "描述")
	if !strings.Contains(global, "%s $1 <script>alert(1)</script>") || !strings.Contains(global, "退款") || !strings.Contains(global, "status=failed") {
		t.Errorf("scoped alert detail = %q", global)
	}
	scoped := dealerMetricAlertDetail(localization.EN, hostile, "Refunds", "desc")
	if !strings.Contains(scoped, "status=failed") || !strings.Contains(scoped, "%s $1 <script>alert(1)</script>") {
		t.Errorf("english alert detail = %q", scoped)
	}
	if global == scoped {
		t.Error("alert detail did not follow the locale")
	}
}

func TestFix01C2SummaryTextKeepsArgumentOrder(t *testing.T) {
	cases := []struct {
		critical, warning, errors int
		zhHeadline                string
		zhSnippet                 string
	}{
		{3, 2, 1, "指标需要处理", "发现 3 个严重信号和 2 个警告信号"},
		{0, 7, 0, "系统运行中，有需跟进信号", "有 7 项指标需要关注"},
		{0, 0, 5, "存在指标采集错误", "报告了 5 个采集器错误"},
		{0, 0, 0, "运营指标正常", "未发现需要处理的情况"},
	}
	for _, tc := range cases {
		headline, description := dealerMetricsSummaryText(localization.ZHCN, tc.critical, tc.warning, tc.errors)
		if headline != tc.zhHeadline {
			t.Errorf("summary headline = %q, want %q", headline, tc.zhHeadline)
		}
		if !strings.Contains(description, tc.zhSnippet) {
			t.Errorf("summary description = %q, want it to contain %q", description, tc.zhSnippet)
		}
		enHeadline, enDescription := dealerMetricsSummaryText(localization.EN, tc.critical, tc.warning, tc.errors)
		if enHeadline == headline || enDescription == description {
			t.Errorf("summary text did not follow the locale: %q / %q", enHeadline, enDescription)
		}
	}
}

// The view must pass the request locale into every metrics text helper (wiring contract).
func TestFix01C2ViewWiresRequestLocale(t *testing.T) {
	source := readHandlerSource(t, "dealer.go")
	for _, token := range []string{
		"dealerMetricGroupText(loc, key)",
		"dealerMetricNarrative(loc, item)",
		"dealerMetricDisplayName(loc, item.name)",
		"dealerMetricAlertDetail(loc, item, title, description)",
		"dealerMetricsSummaryText(loc, criticalCount, warningCount, collectionErrors)",
		"func dealerAdminMetricsView(loc localization.Locale, ctx context.Context, deps DealerDeps, requestedTab string)",
	} {
		if !strings.Contains(source, token) {
			t.Errorf("metrics view wiring missing %q", token)
		}
	}
	// frozen status helpers must stay machine-only
	for _, token := range []string{
		"func dealerMetricHumanStatus(status string, rank int) string",
		"func dealerMetricRankStatus(rank int) (string, string)",
		"func dealerMetricSeriesStatus(name string, labels string, numeric float64, hasNumeric bool) (int, string, string)",
	} {
		if !strings.Contains(source, token) {
			t.Errorf("frozen status helper changed: %q", token)
		}
	}
}

func TestFix01C2LocaleIsolation(t *testing.T) {
	var wg sync.WaitGroup
	for i := range 16 {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			loc, want := localization.ZHCN, "运营积压"
			if i%2 == 1 {
				loc, want = localization.EN, "Operations backlog"
			}
			for range 50 {
				if title, _ := dealerMetricGroupText(loc, "operations"); title != want {
					t.Errorf("locale %s: title = %q, want %q", loc, title, want)
				}
			}
		}(i)
	}
	wg.Wait()
}

func containsCJK(value string) bool {
	for _, r := range value {
		if r >= 0x4E00 && r <= 0x9FFF {
			return true
		}
	}
	return false
}

// metricsViewFixtureDeps builds non-nil repositories over a gorm handle that is never
// dialled: gorm.Open with DisableAutomaticPing=true returns without connecting, the DSN
// points at an unbound local port, and the tests pass an already-cancelled context so every
// read-only Count/List call fails with context.Canceled before any socket work. No real
// database, no credentials and no write path is touched; the connection is test-owned and
// closed by Cleanup.
func metricsViewFixtureDeps(t *testing.T) DealerDeps {
	t.Helper()
	db, err := gorm.Open(postgres.New(postgres.Config{
		DSN: "postgres://fixture:fixture@127.0.0.1:1/gateway_metrics_fixture?sslmode=disable&connect_timeout=1",
	}), &gorm.Config{
		DisableAutomaticPing: true,
		Logger:               logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		t.Fatalf("fixture gorm open: %v", err)
	}
	if sqlDB, dbErr := db.DB(); dbErr == nil {
		t.Cleanup(func() { _ = sqlDB.Close() })
	}
	return DealerDeps{
		WebhookDeliveryRepo:     repositories.NewWebhookDeliveryRepo(db),
		MoneyEventOutboxRepo:    repositories.NewMoneyEventOutboxRepo(db),
		MoneyEventInboxRepo:     repositories.NewMoneyEventInboxRepo(db),
		WorkerLeaseRepo:         repositories.NewWorkerLeaseRepo(db),
		SweepJobRepo:            repositories.NewSweepJobRepo(db),
		OutboundRepo:            repositories.NewOutboundTransactionRepo(db),
		WithdrawalRepo:          repositories.NewWithdrawalRequestRepo(db),
		RefundRepo:              repositories.NewRefundRepo(db),
		ReconciliationRepo:      repositories.NewReconciliationRepo(db),
		ChainStateRepo:          repositories.NewChainStateRepo(db),
		ProviderHealthRepo:      repositories.NewProviderHealthRepo(db),
		WalletAddressLookupRepo: repositories.NewWalletAddressLookupRepo(db),
		TransactionRepo:         repositories.NewTransactionRepo(db),
		PaymentRepo:             repositories.NewPaymentRepo(db),
		ProductRepo:             repositories.NewProductRepo(db),
		ActivityLogRepo:         repositories.NewActivityLogRepo(db),
		AssetRegistry:           nil, // factory_not_configured path stays visible in the raw metrics
		Blockchains:             nil,
	}
}

// TestFix01C2ActualMetricsViewLocale is the restored actual-view assertion demanded by the
// supervisor: it drives the real dealerAdminMetricsView for both locales over a fully
// initialised (non-nil) repository set in a controlled read-only failure state
// (context.Canceled -> query_failed / factory_not_configured raw metrics). It proves the
// localized view text, not database or runtime health.
func TestFix01C2ActualMetricsViewLocale(t *testing.T) {
	deps := metricsViewFixtureDeps(t)
	cancelled, cancel := context.WithCancel(context.Background())
	cancel()

	zhSummary, zhGroups, zhAlerts, _, _, zhRaw := dealerAdminMetricsView(localization.ZHCN, cancelled, deps, "")
	enSummary, enGroups, enAlerts, _, _, enRaw := dealerAdminMetricsView(localization.EN, cancelled, deps, "")

	if len(zhGroups) == 0 || len(enGroups) == 0 {
		t.Fatalf("expected metric groups from the actual view, got zh=%d en=%d", len(zhGroups), len(enGroups))
	}
	if len(zhGroups) != len(enGroups) {
		t.Fatalf("group count changed with the locale: zh=%d en=%d", len(zhGroups), len(enGroups))
	}
	if !containsCJK(zhSummary.Headline) || containsCJK(enSummary.Headline) {
		t.Errorf("summary headline locale mismatch: zh=%q en=%q", zhSummary.Headline, enSummary.Headline)
	}
	if zhSummary.Headline == enSummary.Headline {
		t.Errorf("summary headline is not localized: %q", zhSummary.Headline)
	}
	if !containsCJK(zhSummary.Description) || zhSummary.Description == enSummary.Description {
		t.Errorf("summary description is not localized: zh=%q", zhSummary.Description)
	}
	// The raw metrics body is locale-independent and must be byte-identical.
	if zhRaw != enRaw {
		t.Errorf("raw metrics body changed with the locale:\nzh=%q\nen=%q", zhRaw, enRaw)
	}
	if !strings.Contains(zhRaw, "query_failed") && !strings.Contains(zhRaw, "factory_not_configured") {
		t.Errorf("raw metrics body does not show the controlled collector failure: %q", zhRaw)
	}

	// machine fields must match; CheckedAt is a clock value and is never compared.
	if zhSummary.TotalSeries != enSummary.TotalSeries || zhSummary.TotalGroups != enSummary.TotalGroups ||
		zhSummary.CollectionErrors != enSummary.CollectionErrors || zhSummary.Status != enSummary.Status ||
		zhSummary.StatusClass != enSummary.StatusClass || zhSummary.Tone != enSummary.Tone ||
		zhSummary.AttentionCount != enSummary.AttentionCount {
		t.Errorf("summary machine fields changed with locale: zh=%+v en=%+v", zhSummary, enSummary)
	}

	enGroupsByKey := make(map[string]DealerMetricGroupView, len(enGroups))
	for _, group := range enGroups {
		if _, dup := enGroupsByKey[group.Key]; dup {
			t.Fatalf("duplicate group key %q in the english view", group.Key)
		}
		enGroupsByKey[group.Key] = group
	}
	zhGroupsByKey := make(map[string]DealerMetricGroupView, len(zhGroups))
	for _, group := range zhGroups {
		if _, dup := zhGroupsByKey[group.Key]; dup {
			t.Fatalf("duplicate group key %q in the zh view", group.Key)
		}
		zhGroupsByKey[group.Key] = group
	}
	for _, zhGroup := range zhGroups {
		enGroup, ok := enGroupsByKey[zhGroup.Key]
		if !ok {
			t.Errorf("group %q exists only in zh", zhGroup.Key)
			continue
		}
		if !containsCJK(zhGroup.Title) || zhGroup.Title == enGroup.Title {
			t.Errorf("group %q title not localized: %q", zhGroup.Key, zhGroup.Title)
		}
		if !containsCJK(zhGroup.Summary) || zhGroup.Summary == enGroup.Summary {
			t.Errorf("group %q summary not localized: %q", zhGroup.Key, zhGroup.Summary)
		}
		if zhGroup.TotalCount != enGroup.TotalCount || zhGroup.HealthyCount != enGroup.HealthyCount ||
			zhGroup.WarningCount != enGroup.WarningCount || zhGroup.CriticalCount != enGroup.CriticalCount ||
			zhGroup.HealthPercent != enGroup.HealthPercent || zhGroup.Status != enGroup.Status ||
			zhGroup.StatusClass != enGroup.StatusClass || zhGroup.Tone != enGroup.Tone {
			t.Errorf("group %q machine fields changed: zh=%+v en=%+v", zhGroup.Key, zhGroup, enGroup)
		}
		if len(zhGroup.Items) != len(enGroup.Items) {
			t.Errorf("group %q item count changed: zh=%d en=%d", zhGroup.Key, len(zhGroup.Items), len(enGroup.Items))
		}
		// several series share one metric name and differ only by labels, so the pair key
		// must include the labels to keep every series compared exactly once.
		enItems := make(map[string]DealerMetricView, len(enGroup.Items))
		for _, item := range enGroup.Items {
			pairKey := item.Name + "|" + item.Labels
			if _, dup := enItems[pairKey]; dup {
				t.Fatalf("duplicate item key %q in group %q", pairKey, zhGroup.Key)
			}
			enItems[pairKey] = item
		}
		for _, zhItem := range zhGroup.Items {
			enItem, ok := enItems[zhItem.Name+"|"+zhItem.Labels]
			if !ok {
				t.Errorf("group %q item %q labels=%q exists only in zh", zhGroup.Key, zhItem.Name, zhItem.Labels)
				continue
			}
			if !containsCJK(zhItem.DisplayName) || zhItem.DisplayName == enItem.DisplayName {
				t.Errorf("item %q labels=%q display name not localized: %q", zhItem.Name, zhItem.Labels, zhItem.DisplayName)
			}
			if zhItem.Description != "" && (!containsCJK(zhItem.Description) || zhItem.Description == enItem.Description) {
				t.Errorf("item %q labels=%q description not localized: %q", zhItem.Name, zhItem.Labels, zhItem.Description)
			}
			if zhItem.Action != "" && (!containsCJK(zhItem.Action) || zhItem.Action == enItem.Action) {
				t.Errorf("item %q labels=%q action not localized: %q", zhItem.Name, zhItem.Labels, zhItem.Action)
			}
			if zhItem.Status != enItem.Status || zhItem.StatusClass != enItem.StatusClass ||
				zhItem.Tone != enItem.Tone || zhItem.IsProblem != enItem.IsProblem ||
				zhItem.Help != enItem.Help || zhItem.Labels != enItem.Labels {
				t.Errorf("item %q labels=%q machine fields changed: zh=%+v en=%+v", zhItem.Name, zhItem.Labels, zhItem, enItem)
			}
			// exact comparison: under the cancelled context every read-only collector fails with
			// query_failed/factory_not_configured, so no age/time metric exists and the raw value
			// must be byte-identical between the two view builds.
			if zhItem.Value != enItem.Value {
				t.Errorf("item %q labels=%q raw value changed: zh=%q en=%q", zhItem.Name, zhItem.Labels, zhItem.Value, enItem.Value)
			}
		}
	}

	if len(zhAlerts) != len(enAlerts) {
		t.Fatalf("alert count changed with locale: zh=%d en=%d", len(zhAlerts), len(enAlerts))
	}
	// Alerts are ranked lists; ties keep an implementation-defined order, so they are compared
	// as a set keyed by metric+labels (every series still compared exactly once).
	enAlertsByKey := make(map[string]DealerMetricAlertView, len(enAlerts))
	for _, alert := range enAlerts {
		pairKey := alert.Metric + "|" + alert.Labels
		if _, dup := enAlertsByKey[pairKey]; dup {
			t.Fatalf("duplicate alert key %q", pairKey)
		}
		enAlertsByKey[pairKey] = alert
	}
	for _, zhAlert := range zhAlerts {
		enAlert, ok := enAlertsByKey[zhAlert.Metric+"|"+zhAlert.Labels]
		if !ok {
			t.Errorf("alert %q labels=%q exists only in zh", zhAlert.Metric, zhAlert.Labels)
			continue
		}
		if zhAlert.Rank != enAlert.Rank || zhAlert.Status != enAlert.Status ||
			zhAlert.StatusClass != enAlert.StatusClass || zhAlert.Tone != enAlert.Tone ||
			zhAlert.Value != enAlert.Value {
			t.Errorf("alert %q labels=%q machine fields changed: zh=%+v en=%+v", zhAlert.Metric, zhAlert.Labels, zhAlert, enAlert)
		}
		if !containsCJK(zhAlert.Group) || zhAlert.Group == enAlert.Group {
			t.Errorf("alert %q group label not localized: %q", zhAlert.Metric, zhAlert.Group)
		}
		if !containsCJK(zhAlert.Title) || zhAlert.Title == enAlert.Title {
			t.Errorf("alert %q title not localized: %q", zhAlert.Metric, zhAlert.Title)
		}
		if !containsCJK(zhAlert.Detail) || zhAlert.Detail == enAlert.Detail {
			t.Errorf("alert %q detail not localized: %q", zhAlert.Metric, zhAlert.Detail)
		}
	}
}
